  function refreshHomeIntent(){const existing=hasAssessment(),conv=conversation(),live=!!conv.latest;$('home-intent').textContent=existing?'Start a new assessment. Your current project stays saved.':'Start with what you need to understand.';$('home-submit').setAttribute('aria-label',existing?'Start a new assessment':'Find relevant experts');$('resume-search').hidden=!live&&!project()?.activeBrief&&!pendingQuestion();$('resume-search').textContent=(pendingQuestion()?'Continue conversation: ':live?'Resume & refine ':'Resume discovery: ')+(project()?.name||'current assessment')+' →';$('other-home-draft').hidden=existing||!conv.homeDraft.trim()||conv.homeDraft===conv.draft;setBusy(conv.busy);}
